  --color-basis: #ffffff;
  --color-primary: #000000;
  --color-secondary: #5c6165;
  --color-ternary: #888888;
  --color-peripheral: #cdcdcd;
  --color-auxilary: #828282;
  --color-contrast: #111111;
  --color-quote: #e8e8e8;
  --color-highlight: #2a7ae2;
  --color-warning: #e2362a;

