@font-face {
  font-family: 'Wermut';
  src: url('../fonts/wermut-regular.otf') format('opentype');
  font-weight: 400;
  font-style: normal;
}

@font-face {
  font-family: 'Wermut';
  src: url('../fonts/wermut-italic.otf') format('opentype');
  font-weight: 400;
  font-style: italic;
}

@font-face {
  font-family: 'Signifier';
  src: url('../fonts/signifier-regular.ttf') format('truetype');
  font-weight: 400;
  font-style: normal;
}

@font-face {
  font-family: 'Signifier';
  src: url('../fonts/signifier-regular-italic.ttf') format('truetype');
  font-weight: 400;
  font-style: italic;
}

@font-face {
  font-family: 'Signifier';
  src: url('../fonts/signifier-bold.ttf') format('truetype');
  font-weight: 700;
  font-style: normal;
}

i, em {
  font-family: 'Signifier', serif;
  font-style: italic;
}

a,
a:visited {
  color: var(--color-highlight);
}

a:hover {
  color: var(--color-primary);
}

::selection {
  background-color: var(--color-primary);
  color: var(--color-basis);
}

a::selection {
  background-color: var(--color-highlight);
}

.post-content img::selection {
  background-color: color-mix(in srgb, var(--color-highlight) 50%, transparent);
}

.post-content .cupan-tae {
  cursor: var(--cursor-default) 14 5, auto;
}

.post i, .post em {
  font-family: serif !important;
}

input:-webkit-autofill,
input:-webkit-autofill:hover,
input:-webkit-autofill:focus,
input:-webkit-autofill:active {
  -webkit-box-shadow: 0 0 0 1000px var(--color-contrast) inset !important;
  -webkit-text-fill-color: var(--color-highlight) !important;
  transition: background-color 9999s ease-in-out 0s;
}

input[type="checkbox"] {
  accent-color: var(--color-highlight);
}

*:focus,
*:focus-visible {
  outline: none;
  box-shadow: none;
}

mjx-math {
  white-space: normal !important;
  line-height: normal !important;
}

blockquote {
  color: var(--color-auxilary);
  border-left: 3px solid var(--color-quote);
  padding-left: 25px;
  font-size: 1.2rem;
  font-style: italic;
}

body {
  cursor: var(--cursor-default) 14 5, auto;
}

a,
button,
[role="button"],
input[type="submit"],
input[type="button"],
input[type="checkbox"],
label,
select,
.post-content img,
.img-overlay-close {
  cursor: var(--cursor-pointer), pointer;
}

.cupan-tae {
  content: var(--site-lilies);
}

.site-nav .menu-icon>svg path {
  fill: var(--color-ternary);
}

.spline {
  position: fixed;
  top: 0;
  left: 50%;
  width: 3px;
  height: 100vh;
  background-color: var(--color-peripheral);
  transform: translateX(-50%);
  z-index: 0;
}

body {
  color: var(--color-primary);
  background: var(--color-basis);
  font-family: monospace;
}

sup {
  font-size: 0.75em;
  line-height: 0;
  vertical-align: baseline;
  position: relative;
  font-weight: 600;
  top: -0.4em;
}

.page {
  padding: 10px 20px 0px 20px;
  z-index: 3;
}

.page-content {
  font-family: serif;
  line-height: 1.3;
  font-size: 20px;
  overflow-x: hidden;
}

h1,
h2,
h3,
h4,
h5,
h6 {
  font-family: 'Wermut', serif;
  color: var(--color-secondary);
  letter-spacing: -0.02em;
}

.wrapper {
  max-width: calc(650px - (30px));
  z-index: 3;
}

.trigger {
  background: var(--color-basis);
}

.trigger .page-link {
  color: var(--color-primary);
}

.footer-col {
  text-align: left;
}

.post-content h1,
h2,
h3,
h4,
h5,
h6 {
  height: 46px;
}

.site-logo {
  height: 35px;
  content: var(--site-logo);
}

.p-meta {
  color: var(--color-peripheral);
}

.p-author {
  font-weight: 400;
  color: var(--color-primary);
  font-family: 'Signifier';
}

.post-header {
  margin-bottom: 10px;
  margin-top: 70px;
}

.post-image {
  display: none;
}

.post-signoff { 
  display: none;
}

.site-header {
  margin-top: 10px;
  border-top: none;
  padding-bottom: 5px;
  border-bottom: none;
  margin-left: 13px;
  margin-right: 13px;
}

.site-footer {
  border-top: none;
  padding: 30px 5px;
}

.site-footer .footer-col-wrapper {
  display: flex;
  flex-direction: row;
  justify-content: space-between;
  align-items: center;
  width: 100%;
  margin-left: 0;
}

.site-footer .footer-col {
  width: auto !important;
  float: none !important;
  padding-left: 0;
  margin-bottom: 0;
}

.contact-list,
.idiom {
  float: none;
}

#ref-section {
  margin-bottom: 80px;
}

.post-list {
  height: 70vh;
  display: flex;
  justify-content: center;
  align-items: center;
}

.post-list li {
  border: solid 3px var(--color-peripheral);
  border-radius: 0px;
  background: var(--color-basis);
  z-index: 3;
  padding: 30px 30px;
  position: relative;
  color: var(--color-primary);
}

.post-list li h2 {
  height: auto;
  font-size: 30px;
  margin-bottom: 12px !important;
}

.post-list li a {
  margin-block-start: 0px;
  color: var(--color-primary);
}

.post-list li a:hover {
  text-decoration: none;
}

.post-description {
  text-decoration: none;
  font-size: 19px;
}

.post-meta {
  font-size: 19px;
  font-family: "Signifier";
}

.post-list li:hover {
  border-color: var(--color-ternary);
}

.post-list li a h2 {
  margin-bottom: 3px;
}

.post-list li:hover {
  transform: translateY(-3.5px);
}

.post-image {
  margin-bottom: 10px;
}

.post-image,
.post img {
  width: 100%;
  margin-top: 25px;
  margin-bottom: 15px;
}

.idiom {
  float: right;
  color: var(--color-peripheral);
}

.contact-list {
  float: left;
}

.post-content h2 {
  margin-top: 6px;
}

.post-content {
  position: relative;
  margin-bottom: 90px;
}

table {
  margin-left: auto;
  margin-right: auto;
  width: 80%;
}

td {
  font-size: 12px
}

figcaption {
  margin-top: 12px;
  text-align: center;
  font-style: italic;
  font-size: 0.95em;
}

.post-content h2,
.post-content h3 {
  opacity: 0;
  margin: 0;
  padding: 0;
}

.toc {
  position: absolute;
  top: 0;
  left: calc(10% - 180px);
  height: 100%;
  width: 360px;
  font-family: 'Signifier';
  font-size: 0.95em;
  overflow-y: hidden;
  overflow-x: visible;
}

.toc ul {
  list-style: none;
  padding: 0;
  margin: 0;
}

.toc li {
  position: relative;
}

.toc a {
  text-decoration: none;
  color: var(--color-peripheral);
  display: block;
  padding: 4px 0px 0px 20px;
}

.site-footer .footer-col-wrapper {
  display: flex;
  flex-direction: row;
  justify-content: space-between;
  align-items: center;
  width: 100%;
  margin-left: 0;
}

.site-footer .footer-col {
  width: auto !important;
  float: none !important;
  padding-left: 0;
  margin-bottom: 0;
}

.contact-list,
.idiom {
  float: none;
}

.toc a.active {
  color: var(--color-primary);
}

.post-wrapper {
  position: relative;
}

.site-footer .footer-col-wrapper {
  display: flex;
  flex-direction: row;
  justify-content: space-between;
  align-items: center;
  width: 100%;
  margin-left: 0;
}

.site-footer .footer-col {
  width: auto !important;
  float: none !important;
  padding-left: 0;
  margin-bottom: 0;
}

.contact-list,
.idiom {
  float: none;
  margin: 0px;
}

.nav-back-btn {
  position: relative;
  display: none;
}

.nav-back-btn a {
  position: absolute;
  font-size: 35px;
  color: var(--color-peripheral);
  left: 0px;
  margin-left: -135px;
  text-decoration: none !important;
}

.nav-back-btn a:hover {
  color: var(--color-primary);
}

.mailing-list {
  display: none;
}

.trigger .page-link {
  margin-right: 5px !important;
}

.img-overlay {
  display: none;
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.65);
  z-index: 999;
  align-items: center;
  justify-content: center;
}

.img-overlay.active {
  display: flex;
}

.img-overlay img {
  max-width: 90vw;
  max-height: 90vh;
  object-fit: contain;
}

.img-overlay-close {
  position: fixed;
  top: 16px;
  right: 20px;
  color: var(--color-primary);
  font-size: 22px;
  opacity: .7;
  line-height: 1;
}

.img-overlay-close:hover {
  opacity: 1;
}

.post-content img:not(.cupan-tae) {
  transition: opacity .15s;
}

.post-content img:not(.cupan-tae):hover {
  opacity: 0.8;
}

.modal {
  display: none;
}

.modal.is-open {
  display: block;
}

.modal__overlay {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.45);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 9999;
}

.modal__container {
  background: var(--color-basis);
  padding: 2.5rem;
  width: min(480px, 75vw);
  will-change: transform, opacity;
}

@keyframes mlSlideUp {
  from {
    transform: translateY(60px);
    opacity: 0;
  }

  to {
    transform: translateY(0);
    opacity: 1;
  }
}

@keyframes mlSpanUp {
  from {
    transform: translateY(0);
    opacity: 1;
  }

  to {
    transform: translateY(-80px);
    opacity: 0;
  }
}

.modal__container[data-state="opening"] {
  animation: mlSlideUp 0.42s cubic-bezier(0.16, 1, 0.3, 1) forwards;
}

.modal__container[data-state="closing"] {
  animation: mlSpanUp 0.28s cubic-bezier(0.4, 0, 1, 1) forwards;
}

.modal__header {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  margin-bottom: 2rem;
  margin-top: -1rem;
}

.modal__title {
  font-size: 2rem;
  font-weight: 500;
  font-family: "Signifier";
  margin: 0;
}

.modal__close {
  background: none;
  border: none;
  padding: 0;
}

.modal__content {
  font-family: 'Signifier';
}

.modal__close::before {
  content: '×';
  font-size: 2rem;
  color: var(--color-auxilary);
}

.modal__desc {
  font-size: 1.2rem;
  color: var(--color-primary);
  margin-bottom: 1.5rem;
  line-height: 1.3;
}

.modal__form {
  display: flex;
  border: 2px solid var(--color-peripheral);
}

#ml-email {
  flex: 1;
  border: none;
  outline: none;
  padding: 0.65rem 0.85rem;
  font-size: 0.9rem;
  font-family: monospace;
  background: var(--color-secondary);
  color: var(--color-basis);
}

#ml-email::placeholder {
  color: var(--color-peripheral);
}

#ml-submit {
  border: none;
  border-left: 2px solid var(--color-peripheral);
  background: var(--color-contrast);
  color: var(--color-basis);
  padding: 0.65rem 1.1rem;
  font-size: 0.8rem;
  text-transform: uppercase;
  font-family: monospace;
}

#ml-submit:hover {
  background: transparent;
  color: var(--color-primary);
}

#ml-status {
  font-size: 1.2rem;
  margin-top: 2rem;
  min-height: 1.2em;
  font-family: 'Signifier';
}

#ml-status.error {
  color: var(--color-warning);
}

#ml-status.success {
  color: var(--color-highlight);
}

.toc-line {
  position: absolute;
  left: 0;
  top: 0;
  bottom: 0;
  width: 3px;
  background-color: var(--color-peripheral);
}

.toc-progress {
  position: absolute;
  left: 1px; /* horizontal center of the 3px .toc-line */
  top: 0;
  width: 8px;
  height: 14px;
  background-color: var(--color-primary);
  transform: translate(-50%, 0px);
  will-change: transform;
  transition: transform 0.08s linear;
  pointer-events: none;
  z-index: 100;
}

.toc-tick {
  position: absolute;
  top: 9px;
  left: 1px;
  width: 5px;
  height: 14px;
  background-color: var(--color-peripheral);
}

.toc li.active .toc-tick {
  background-color: var(--color-basis);
}

@media (max-width: 1024px) {

  .site-header { 
    margin-left: -2px;
    margin-right: 0px;
  }

  .nav-back-btn {
    display: none;
  }

  .toc {
    display: none;
  }

  .post-content h2,
  .post-content h3 {
    opacity: 0;
    display: none;
  }

}

@media (max-width: 624px) {

  .post-signoff {
    display: contents;
  }

  mjx-math {
    line-height: 0.4em !important;
  }

  .mailing-list {
    display: block;
    line-height: 1.5;
    padding: 5px 10px;
  }

  .post-content h1,
  h2,
  h3,
  h4,
  h5,
  h6 {
    height: 20px;
  }

  .site-nav {
    background: none;
    border: 2.5px solid var(--color-peripheral);
    border-radius: 0px;
    margin-top: 8px;
  }

  .post-header {
    margin-top: 20px;
  }

  .site-footer {
    padding: 30px 0px;
  }

}
